//! The ribbon and chrome description of one application, as data.
//!
//! The JSON files in `spec/` are generated by `tools/gen_spec.py` from the oracle reference
//! (`fixtures/reference/ui`). Lengths are `u`: physical pixels at the reference scale
//! ([`REF_SCALE`]); the layout engine converts them to the scale in use.

use serde::Deserialize;

/// The display scale the reference was measured at (125 %).
pub const REF_SCALE: f32 = 1.25;

/// What a control looks and behaves like.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    Button,
    Split,
    Dropdown,
    Combo,
    Spinner,
    Edit,
    Checkbox,
    Gallery,
    // Chrome only.
    File,
    Avatar,
    Caption,
    Title,
    Search,
    Slider,
}

/// How tall a ribbon control is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Size {
    #[default]
    Small,
    Tall,
    Large,
}

/// One command shown in the ribbon: data only. `id` is the handler key the application wires.
#[derive(Debug, Clone, Deserialize)]
pub struct Control {
    pub id: String,
    pub label: String,
    pub kind: Kind,
    pub w: i32,
    #[serde(default)]
    pub h: Option<i32>,
    #[serde(default)]
    pub size: Size,
    #[serde(default)]
    pub arrow_w: Option<i32>,
    #[serde(default)]
    pub arrow_h: Option<i32>,
    #[serde(default)]
    pub value: Option<String>,
    #[serde(default = "yes")]
    pub enabled: bool,
    #[serde(default)]
    pub icon: Option<String>,
    #[serde(default)]
    pub gap: Option<i32>,
    /// Name the control has in the reference tree (for the geometry test only).
    #[serde(default)]
    pub ref_name: Option<String>,
    /// Key tip after the tab's own (`FP` for Alt, H, F, P), measured from the reference.
    #[serde(default)]
    pub key: Option<String>,
}

fn yes() -> bool {
    true
}

impl Control {
    /// Height in `u`.
    pub fn height(&self) -> i32 {
        self.h.unwrap_or(match self.size {
            Size::Large => 96,
            _ => 30,
        })
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Row {
    #[serde(default)]
    pub slot: Option<String>,
    #[serde(default)]
    pub y: Option<i32>,
    #[serde(default)]
    pub dx: i32,
    pub items: Vec<Control>,
}

impl Row {
    /// Top of the row slot below the group top, in `u`.
    pub fn top(&self) -> i32 {
        match self.slot.as_deref() {
            Some("t0") => 2,
            Some("t1") => 34,
            Some("t2") => 66,
            Some("c0") => 12,
            Some("c1") => 52,
            _ => self.y.unwrap_or(2),
        }
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Block {
    #[serde(default)]
    pub gap: Option<i32>,
    pub rows: Vec<Row>,
}

/// How much of a group the ribbon shows at some window width. Groups shrink in this order: `Large`
/// (tall buttons, label under the icon), `Medium` (labels beside icons), `Small` (icons only), then
/// `Collapsed`: one group button that opens the full group in a popup.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Scale {
    #[default]
    Large,
    Medium,
    Small,
    Collapsed,
}

/// A layout a group passes through as the window narrows (state 0 is the group itself).
#[derive(Debug, Clone, Deserialize)]
pub struct GroupState {
    pub scale: Scale,
    /// Natural width; the group may squeeze down to `min_w` (label wider than its content).
    pub w: i32,
    #[serde(default)]
    pub min_w: Option<i32>,
    /// The content sits centred in the group (squeezable groups).
    #[serde(default)]
    pub center: bool,
    pub launcher: bool,
    #[serde(default)]
    pub pad_left: i32,
    #[serde(default)]
    pub pad_right: i32,
    #[serde(default)]
    pub blocks: Vec<Block>,
}

/// One state of a group, borrowed (state 0 lives in the [`Group`] itself).
#[derive(Debug, Clone, Copy)]
pub struct StateRef<'a> {
    pub scale: Scale,
    pub w: i32,
    pub min_w: Option<i32>,
    pub center: bool,
    pub launcher: bool,
    pub pad_left: i32,
    pub pad_right: i32,
    pub blocks: &'a [Block],
}

#[derive(Debug, Clone, Deserialize)]
pub struct Group {
    pub id: String,
    pub label: String,
    #[serde(default)]
    pub ref_name: Option<String>,
    pub launcher: bool,
    /// Key tip of the dialog launcher, after the tab's own.
    #[serde(default)]
    pub launcher_key: Option<String>,
    /// Key tip of the collapsed group button (opens the popup), after the tab's own.
    #[serde(default)]
    pub popup_key: Option<String>,
    /// Icon of the collapsed group button.
    #[serde(default)]
    pub icon: Option<String>,
    /// Measured width of state 0: a group is never narrower than this when its label or launcher needs it.
    pub w: i32,
    #[serde(default)]
    pub scale: Scale,
    #[serde(default)]
    pub min_w: Option<i32>,
    #[serde(default)]
    pub center: bool,
    #[serde(default)]
    pub pad_left: i32,
    #[serde(default)]
    pub pad_right: i32,
    pub blocks: Vec<Block>,
    /// Narrower layouts, widest first (state 1, 2...).
    #[serde(default)]
    pub states: Vec<GroupState>,
}

impl Group {
    /// Number of states, including state 0.
    #[must_use]
    pub fn state_count(&self) -> usize {
        1 + self.states.len()
    }

    /// State `i` (0 is the widest). Out-of-range indices give the narrowest state.
    #[must_use]
    pub fn state(&self, i: usize) -> StateRef<'_> {
        match i.checked_sub(1).and_then(|k| self.states.get(k)) {
            Some(s) => StateRef {
                scale: s.scale,
                w: s.w,
                min_w: s.min_w,
                center: s.center,
                launcher: s.launcher,
                pad_left: s.pad_left,
                pad_right: s.pad_right,
                blocks: &s.blocks,
            },
            None if i > 0 && !self.states.is_empty() => self.state(self.states.len()),
            None => StateRef {
                scale: self.scale,
                w: self.w,
                min_w: self.min_w,
                center: self.center,
                launcher: self.launcher,
                pad_left: self.pad_left,
                pad_right: self.pad_right,
                blocks: &self.blocks,
            },
        }
    }

    /// Every control of state 0 (the full group, as the popup shows it).
    pub fn controls(&self) -> impl Iterator<Item = &Control> {
        self.blocks
            .iter()
            .flat_map(|b| &b.rows)
            .flat_map(|r| &r.items)
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Tab {
    pub id: String,
    pub label: String,
    pub w: i32,
    #[serde(default, rename = "ref")]
    pub reference: Option<String>,
    /// Key tip after Alt (`H`, `JI`), measured from the reference.
    #[serde(default)]
    pub key: Option<String>,
    pub groups: Vec<Group>,
    /// Shrink steps in order as the window narrows: each step sets groups to states
    /// (`[group, state]`), measured from the responsive reference.
    #[serde(default)]
    pub steps: Vec<Vec<[usize; 2]>>,
}

/// A fixed chrome widget, positioned relative to the ribbon pane.
#[derive(Debug, Clone, Deserialize)]
pub struct Chrome {
    pub id: String,
    pub label: String,
    pub kind: Kind,
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
    /// Distance from the right edge of the container, for right-anchored widgets.
    pub right: i32,
    #[serde(default = "yes")]
    pub enabled: bool,
    #[serde(default)]
    pub arrow_w: Option<i32>,
    #[serde(default)]
    pub icon: Option<String>,
    #[serde(default)]
    pub thumb: Option<[i32; 4]>,
    #[serde(default)]
    pub ref_name: Option<String>,
}

#[derive(Debug, Clone, Copy, Deserialize)]
pub struct Rect4 {
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Qat {
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
    pub items: Vec<Chrome>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Lower {
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
}

#[derive(Debug, Clone, Deserialize)]
pub struct StatusSpec {
    pub y_from_bottom: i32,
    pub h: i32,
    pub x: i32,
    pub w: i32,
    pub items: Vec<Chrome>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SheetTabs {
    pub y: i32,
    pub h: i32,
    pub x: i32,
    pub items: Vec<Chrome>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct FormulaBar {
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
    pub right: i32,
}

#[derive(Debug, Clone, Deserialize)]
pub struct NavItem {
    pub label: String,
    pub id: String,
    pub y: i32,
    pub h: i32,
    pub w: i32,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Backstage {
    pub nav: Vec<NavItem>,
    pub nav_x: i32,
    pub nav_w: i32,
}

/// One width of the Quick Access Toolbar. As the window narrows the toolbar keeps fewer of its
/// leading items and ends with the overflow button (the last item of `Qat::items`).
#[derive(Debug, Clone, Deserialize)]
pub struct QatStage {
    /// Number of leading items kept.
    pub keep: usize,
    /// Width of the toolbar in this stage (`u`).
    pub width: i32,
    /// The stage is used while the window is at least `width + min_rest` wide (`u`).
    pub min_rest: i32,
    /// The title row is laid out as if the window were at least this wide (Office holds the row
    /// still between this width and the next stage).
    #[serde(default)]
    pub freeze: Option<i32>,
}

/// The search box (wide window) and its button form (narrow window).
#[derive(Debug, Clone, Deserialize)]
pub struct SearchRules {
    /// The box is shown from this client width (`u`) upward.
    pub box_min_cw: i32,
    /// Box width as a percentage of the client width, up to `max_w`.
    pub ratio_pct: i32,
    pub max_w: i32,
    /// Leftmost x of the box (the title keeps its minimum width).
    pub pin_x: i32,
    /// Distance from the box or button to the user widget.
    pub gap: i32,
    pub button_w: i32,
    pub button_y: i32,
    pub button_h: i32,
}

/// How the title row responds to a narrower window.
#[derive(Debug, Clone, Deserialize)]
pub struct TitleRules {
    pub qat: Vec<QatStage>,
    /// The document title never gets narrower than this; the user widget, then the search button
    /// leave instead.
    pub min_w: i32,
    pub search: SearchRules,
}

/// One width of the tab row's right-hand buttons (Comments, Editing, Share).
#[derive(Debug, Clone, Deserialize)]
pub struct ClusterStage {
    /// The stage is used from this client width (`u`) upward.
    pub min_cw: i32,
    /// Width of each button of `AppSpec::tab_row_right` (display options excluded).
    pub widths: Vec<i32>,
}

/// How the tab row responds to a narrower window.
#[derive(Debug, Clone, Deserialize)]
pub struct TabRules {
    /// Space between tabs.
    pub gap: i32,
    /// Every tab can lose this much width (padding) before the longest ones shrink alone.
    pub rounds: i32,
    /// Narrowest tab.
    pub min_w: i32,
    /// Space between the last tab and the first right-hand button.
    pub right_gap: i32,
    /// Space between right-hand buttons.
    pub item_gap: i32,
    /// Distance of the last right-hand button from the pane edge.
    pub right_margin: i32,
    /// Width of the scroll button shown when the tabs do not fit.
    pub scroll_w: i32,
    pub clusters: Vec<ClusterStage>,
}

/// How the status bar responds to a narrower window.
#[derive(Debug, Clone, Deserialize)]
pub struct StatusRules {
    /// Id of the first item of the right-hand group; items before it are the left-hand items.
    pub right_from: String,
    /// Room right of the right-hand group that the spec does not list (the size box).
    #[serde(default)]
    pub grip: i32,
    /// A left-hand item stays while this much room is left between it and the right-hand group.
    pub min_gap: i32,
    /// Where the left-hand items start.
    pub left_edge: i32,
    /// Item groups of the right-hand group in the order they leave.
    pub drop: Vec<Vec<String>>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ChromeRules {
    pub title: TitleRules,
    pub tabs: TabRules,
    pub status: StatusRules,
}

/// Everything the shell needs to know about one application.
#[derive(Debug, Clone, Deserialize)]
pub struct AppSpec {
    pub app: String,
    pub ref_scale: f32,
    pub ref_window: [i32; 2],
    /// The ribbon pane in the reference window: x, y, w, h.
    pub pane: [i32; 4],
    pub tab_strip: Rect4,
    pub qat: Qat,
    pub title_text: Chrome,
    pub search: Chrome,
    pub file_tab: Chrome,
    pub title: Vec<Chrome>,
    pub tab_row_right: Vec<Chrome>,
    pub lower: Lower,
    pub groups_x: i32,
    pub group_y: i32,
    pub group_h: i32,
    pub tabs: Vec<Tab>,
    pub status: StatusSpec,
    #[serde(default)]
    pub formula_left: Option<Rect4>,
    #[serde(default)]
    pub name_box: Option<Rect4>,
    #[serde(default)]
    pub formula_bar: Option<FormulaBar>,
    #[serde(default)]
    pub sheet_tabs: Option<SheetTabs>,
    #[serde(default)]
    pub col_header_h: Option<i32>,
    #[serde(default)]
    pub row_header_w: Option<i32>,
    pub backstage: Backstage,
    /// Narrow-window rules of the title row, tab row and status bar (hand-written, measured by
    /// `ribbon-oracle.ps1 -ChromeWidths`; see `spec/chrome-*.json`).
    #[serde(default)]
    pub rules: Option<ChromeRules>,
}

impl AppSpec {
    /// The Writer (word processor) description.
    ///
    /// # Panics
    /// Never in practice: the embedded JSON is checked by the crate's tests.
    #[must_use]
    pub fn writer() -> Self {
        Self::parse(include_str!("../spec/writer.json"))
            .with_rules(include_str!("../spec/chrome-writer.json"))
    }

    /// The Sheets (spreadsheet) description.
    ///
    /// # Panics
    /// Never in practice: the embedded JSON is checked by the crate's tests.
    #[must_use]
    pub fn sheets() -> Self {
        Self::parse(include_str!("../spec/sheets.json"))
            .with_rules(include_str!("../spec/chrome-sheets.json"))
    }

    /// Parses a spec. The embedded files are generated, so a parse failure is a build defect.
    ///
    /// # Panics
    /// When `json` is not a valid spec.
    #[must_use]
    pub fn parse(json: &str) -> Self {
        serde_json::from_str(json).expect("embedded ribbon spec is valid")
    }

    fn with_rules(mut self, json: &str) -> Self {
        self.rules = Some(serde_json::from_str(json).expect("embedded chrome rules are valid"));
        self
    }

    /// Tab by id.
    #[must_use]
    pub fn tab(&self, id: &str) -> Option<&Tab> {
        self.tabs.iter().find(|t| t.id == id)
    }
}
